<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3">Rate Configuration</h1><p class="text-secondary">Effective-dated rates.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#modal">Add Rate</button></div><div class="card shadow-sm"><div class="card-body"><table class="table"><thead><tr><th>Group</th><th>Effective Date</th><th>Gas Rate</th><th>Cylinder Price</th><th>Status</th></tr></thead><tbody id="rows"></tbody></table></div></div><div class="modal fade" id="modal"><div class="modal-dialog"><form class="modal-content" id="form"><div class="modal-header"><h5>Add Rate</h5></div><div class="modal-body"><input name="group_id" class="form-control mb-2" type="number" placeholder="Cylinder Group ID" required><input name="effective_date" class="form-control mb-2" type="date" required><input name="gas_rate" class="form-control mb-2" inputmode="decimal" placeholder="Gas rate / kg" required><input name="cylinder_price" class="form-control" inputmode="decimal" value="0.00" placeholder="Cylinder price" required></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div><script>$(function(){function load(){ $.getJSON('<?=e(url('/rates/data'))?>',function(r){let b=$('#rows').empty();r.data.rows.forEach(x=>b.append('<tr><td>'+ $('<span>').text(x.group_name).html()+'</td><td>'+x.effective_date+'</td><td>'+Number(x.gas_rate).toFixed(2)+'</td><td>'+Number(x.cylinder_price).toFixed(2)+'</td><td>'+(x.active?'Active':'Inactive')+'</td></tr>'));});}$('#form').on('submit',function(e){e.preventDefault();$.post('<?=e(url('/rates'))?>',$(this).serialize()).done(function(r){if(r.ok)location.reload();else alert(r.message);}).fail(function(x){alert(x.responseJSON?.message||'Save failed');});});load();});</script>